use hawdb::{
    ProcessMemorySnapshot, RuntimeMemoryReservation, RuntimeTaskContext,
    SearchOutOfCoreGenerationBuildOptions, SearchOutOfCoreGenerationWriter,
    SearchOutOfCoreReader, SearchProjectionDelta, SearchProjectionKind,
    SearchProjectionRow,
};
use std::collections::BTreeMap;
use std::num::NonZeroU64;
use std::time::Instant;

fn report(phase: &str, started: Instant) {
    let memory = ProcessMemorySnapshot::capture().expect("process memory must be available");
    println!("phase={phase} resident_bytes={} peak_resident_bytes={} elapsed_millis={}",
             memory.resident_bytes, memory.peak_resident_bytes, started.elapsed().as_millis());
}

fn main() {
    let root = std::env::args().nth(1).expect("snapshot root is required");
    let _files = hawdb_storage::file_descriptors::ProjectFileDescriptors::acquire(std::path::Path::new(&root), 1024)
        .expect("the explicit descriptor budget must be admitted");
    let started = Instant::now();
    report("before_open", started);
    let mut reader = SearchOutOfCoreReader::open(&root).expect("complete snapshot must reopen");
    println!("generation={} documents={}", reader.generation(), reader.document_count());
    report("after_open", started);
    let update = SearchOutOfCoreGenerationWriter::prepare_delta_with_context(
        &reader,
        SearchProjectionDelta {
            upserts: vec![SearchProjectionRow {
                kind: SearchProjectionKind::Memory,
                external_id: "0000000000000000".into(),
                title: "Cleanup memory probe".into(),
                body: "bounded-search-mutation ".repeat(2731),
                embedding: Some(vec![0.5;384]),
                source_id: None,
                metadata: BTreeMap::from([
                    ("kind".into(),"memory".into()),
                    ("space_id".into(),"default".into())
                ]),
            }],
            ..Default::default()
        },
        SearchOutOfCoreGenerationBuildOptions {
            lexical_build_memory_bytes: NonZeroU64::new(8*1024*1024).unwrap(),
            max_segment_uncompressed_bytes: NonZeroU64::new(64*1024*1024).unwrap(),
            ..Default::default()
        },
        RuntimeTaskContext::default().with_memory_reservation(
            RuntimeMemoryReservation::new(256*1024*1024,0)),
    ).expect("one replacement must prepare");
    report("after_prepare", started);
    let (_, build, _) = update.finish().expect("replacement must publish");
    println!("published_generation={} published_bytes={} cleanup_retry_required={}",
             build.generation, build.generation_bytes, build.cleanup_retry_required);
    report("after_finish", started);
    reader.refresh().expect("complete new head must refresh");
    report("after_refresh", started);
}
